      const Expr *Arg0 = CE->getArg(0);
      if (!Arg0) continue;
      const Expr *Arg = Arg0->IgnoreParenImpCasts();
      if (TargetVar) {
        if (const auto *DRE = dyn_cast<DeclRefExpr>(Arg)) {
          if (DRE->getDecl() == TargetVar->getDecl())
